const feedbackFile = $json['Feedback file path'];
const analysisQuery = $json['Analysis query'];
const contextFilesRaw = $json['Context file paths (comma-separated)'] || '';
const contextFiles = contextFilesRaw
  .split(',')
  .map((s) => s.trim())
  .filter(Boolean);

return [{
  json: {
    feedback_file: feedbackFile,
    context_files: contextFiles,
    analysis_query: analysisQuery,
  },
}];

const item = $input.first().json;
if (item.detail && !item.opportunities) {
  throw new Error(`Analysis failed: ${item.detail}`);
}
return [{ json: { orchestrationResult: item } }];

const result = $json.orchestrationResult;

const sections = result.opportunities.map((opportunity) => {
  const validated = result.validation_result.opportunities.find(
    (v) => v.opportunity_id === opportunity.opportunity_id
  );
  const evidenceCount = validated ? validated.evidence_count : 'n/a';
  const score = validated ? validated.score.total.toFixed(2) : 'n/a';
  const unresolved = validated ? validated.issues.length : 0;
  return [
    `### ${opportunity.opportunity_id}: ${opportunity.title}`,
    `Score: ${score} | Evidence count: ${evidenceCount} | Unresolved deterministic issues: ${unresolved}`,
    opportunity.problem_statement,
  ].join('\n');
});

const summaryMarkdown = [
  `**Run/cache reference:** \`${result.cache_key}\``,
  `**Critic status:** ${result.critic_output.status} | **Revised:** ${result.revised} | **Model requests:** ${result.model_request_count}`,
  `**Total unresolved deterministic issues:** ${result.unresolved_issue_count}`,
  '',
  sections.join('\n\n'),
].join('\n');

return [{ json: { orchestrationResult: result, summaryMarkdown } }];

