const orchestrationResult = $('Parse Orchestration Result').first().json.orchestrationResult;
const opportunityId = $json['opportunity_id'];
const repo = $json['repo'];

return [{
  json: {
    result: orchestrationResult,
    opportunity_id: opportunityId,
    repo: repo,
    approved: true,
    dry_run: false,
    allowed_repos: [repo],
  },
}];

const item = $input.first().json;
if (item.detail && !item.status) {
  throw new Error(`GitHub action failed: ${item.detail}`);
}
return [{ json: { actionResult: item } }];
